// Class championship (juara umum) standings, generated by scripts/class-standings.mjs from the
// private result files. Holds class names and medal counts only, never student names.
import data from "./standings.json";

export type ClassStanding = { class: string; gold: number; silver: number; bronze: number; score: number };
export type Grade = "X" | "XI" | "XII";

const STANDINGS = data as Record<string, ClassStanding[]>;

export const getStandings = (year: number): ClassStanding[] => STANDINGS[String(year)] ?? [];
export const gradeOf = (cls: string) => cls.split(/[ -]/)[0] as Grade;
export const GRADES: Grade[] = ["X", "XI", "XII"];
